<div class="row g-4"><div class="col-lg-8"><img class="detail-image" src="<?=url('images/uploads/'.$photo['file_name'])?>" alt="<?=e($photo['title'])?>"></div><div class="col-lg-4"><h1><?=e($photo['title'])?></h1><p class="text-muted">By <?=e($photo['author'])?> · <?=e($photo['date_time'])?></p><p><?=nl2br(e($photo['description']))?></p><?php if(isLoggedIn() && (int)$photo['user_id']===(int)currentUser()['id']): ?><form method="post" action="<?=url('photo/'.$photo['id'].'/delete')?>" onsubmit="return confirm('Delete this photo?')"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><button class="btn btn-outline-danger btn-sm"><i class="bi bi-trash"></i> Delete photo</button></form><?php endif; ?></div></div><hr class="my-5"><section><h2>Comments (<?=count($comments)?>)</h2><?php foreach($comments as $item): ?><div class="comment"><strong><?=e($item['author'])?></strong><small class="text-muted ms-2"><?=e($item['date_time'])?></small><p class="mb-0 mt-1"><?=nl2br(e($item['comment']))?></p></div><?php endforeach; ?><?php if(isLoggedIn()): ?><form method="post" action="<?=url('photo/'.$photo['id'].'/comments')?>" class="mt-4"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><textarea class="form-control mb-2" name="comment" maxlength="1000" required placeholder="Add a thoughtful comment..."></textarea><button class="btn btn-dark">Post comment</button></form><?php else: ?><p class="text-muted mt-4"><a href="<?=url('login')?>">Login</a> to join the conversation.</p><?php endif; ?></section>
